// Define symbols to analyze
const symbols = ['EURUSD', 'GBPUSD', 'USDJPY'];
const timeframe = 'M30';

return symbols.map(symbol => ({
  json: {
    symbol,
    timeframe
  }
}));

// Build RAG context from historical trades with outcomes
const symbol = $('Set Trading Symbols').item.json.symbol;
const timeframe = $('Set Trading Symbols').item.json.timeframe;
const historicalTrades = $input.all();

let ragContext = 'No historical trades with outcomes available yet.';

if (historicalTrades.length > 0) {
  const contextLines = historicalTrades.map((item, idx) => {
    const data = item.json;
    const outcome = data.is_win === true ? '✓ WIN' : '✗ LOSS';
    const pnl = data.pnl ? `${data.pnl > 0 ? '+' : ''}${parseFloat(data.pnl).toFixed(2)} pips` : 'N/A';

    return `${idx + 1}. [${data.created_at.split('T')[0]}] ${data.direction} - ${outcome}
   Entry: ${parseFloat(data.entry_price).toFixed(5)} | Exit: ${parseFloat(data.actual_exit_price || 0).toFixed(5)}
   P&L: ${pnl} | Confidence: ${(parseFloat(data.confidence) * 100).toFixed(0)}%
   Rationale: ${data.rationale}`;
  });

  // Calculate win rate
  const wins = historicalTrades.filter(t => t.json.is_win === true).length;
  const winRate = ((wins / historicalTrades.length) * 100).toFixed(1);

  ragContext = `Historical Performance for ${symbol}:
Win Rate: ${winRate}% (${wins}/${historicalTrades.length} trades)

Recent Trades:
${contextLines.join('\n\n')}`;
}

return {
  json: {
    symbol,
    timeframe,
    ragContext,
    historicalCount: historicalTrades.length
  }
};

