// Parse and validate Grok's analysis response
let content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('No content in Grok API response');
}

// Clean markdown if present
content = content.trim();
if (content.includes('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

// Parse JSON
let analysis;
try {
  analysis = JSON.parse(content);
} catch (error) {
  throw new Error(`Failed to parse JSON: ${error.message}\nContent: ${content}`);
}

// Validate required fields
const required = ['symbol', 'timeframe', 'direction', 'entry_price', 'stop_loss', 'take_profit', 'confidence', 'analysis'];
for (const field of required) {
  if (analysis[field] === undefined || analysis[field] === null) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Validate direction
if (!['LONG', 'SHORT', 'FLAT'].includes(analysis.direction)) {
  throw new Error(`Invalid direction: ${analysis.direction}. Must be LONG, SHORT, or FLAT.`);
}

// Validate confidence (0 to 1)
const confidence = parseFloat(analysis.confidence);
if (isNaN(confidence) || confidence < 0 || confidence > 1) {
  throw new Error(`Invalid confidence: ${analysis.confidence}. Must be between 0.0 and 1.0.`);
}

// Validate prices
const prices = ['entry_price', 'stop_loss', 'take_profit'];
for (const priceField of prices) {
  const price = parseFloat(analysis[priceField]);
  if (isNaN(price) || price <= 0) {
    throw new Error(`Invalid ${priceField}: ${analysis[priceField]}`);
  }
}

// Convert confidence to proper decimal
analysis.confidence = confidence;

// Add metadata
analysis.timestamp = new Date().toISOString();
analysis.confidencePercentage = (confidence * 100).toFixed(1) + '%';

return { json: analysis };

// Build detailed email for high-confidence trade
const trade = $('Parse & Validate Analysis').item.json;
const emoji = trade.direction === 'LONG' ? '📈' : trade.direction === 'SHORT' ? '📉' : '⏸️';
const confidencePercent = trade.confidencePercentage;

// Calculate Risk/Reward
const risk = Math.abs(trade.entry_price - trade.stop_loss);
const reward = Math.abs(trade.take_profit - trade.entry_price);
const rr = risk > 0 ? `1:${(reward/risk).toFixed(2)}` : 'N/A';

const html = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: Arial, sans-serif; background: #f5f5f5; padding: 20px; margin: 0; }
  .container { background: white; border-radius: 10px; padding: 30px; max-width: 650px; margin: 0 auto; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
  .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 25px; }
  .header h1 { margin: 0; font-size: 24px; }
  .confidence-badge { background: #10b981; color: white; padding: 8px 16px; border-radius: 20px; display: inline-block; font-weight: bold; font-size: 18px; margin-top: 10px; }
  .trade-info { background: #f8fafc; border-radius: 8px; padding: 20px; margin: 20px 0; }
  .info-row { display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px solid #e2e8f0; }
  .info-row:last-child { border-bottom: none; }
  .label { font-weight: 600; color: #64748b; }
  .value { color: #1e293b; font-weight: 500; }
  .direction-long { color: #10b981; font-weight: bold; font-size: 18px; }
  .direction-short { color: #ef4444; font-weight: bold; font-size: 18px; }
  .analysis-section { background: #eff6ff; border-left: 4px solid #3b82f6; padding: 20px; margin: 20px 0; border-radius: 4px; }
  .analysis-section h3 { margin-top: 0; color: #1e40af; }
  .research-section { background: #f0fdf4; border-left: 4px solid #10b981; padding: 20px; margin: 20px 0; border-radius: 4px; }
  .research-section h3 { margin-top: 0; color: #065f46; }
  .notes-section { background: #fef3c7; border-left: 4px solid #f59e0b; padding: 15px; margin: 15px 0; border-radius: 4px; font-size: 14px; }
  .footer { text-align: center; color: #94a3b8; font-size: 13px; margin-top: 30px; padding-top: 20px; border-top: 1px solid #e2e8f0; }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>${emoji} HIGH CONFIDENCE TRADE SIGNAL</h1>
    <div class="confidence-badge">Confidence: ${confidencePercent}</div>
  </div>

  <div class="trade-info">
    <div class="info-row">
      <span class="label">Symbol:</span>
      <span class="value"><strong style="font-size: 18px;">${trade.symbol}</strong></span>
    </div>
    <div class="info-row">
      <span class="label">Direction:</span>
      <span class="value direction-${trade.direction.toLowerCase()}">${trade.direction}</span>
    </div>
    <div class="info-row">
      <span class="label">Timeframe:</span>
      <span class="value">${trade.timeframe}</span>
    </div>
    <div class="info-row">
      <span class="label">Entry Price:</span>
      <span class="value">${parseFloat(trade.entry_price).toFixed(5)}</span>
    </div>
    <div class="info-row">
      <span class="label">Stop Loss:</span>
      <span class="value">${parseFloat(trade.stop_loss).toFixed(5)}</span>
    </div>
    <div class="info-row">
      <span class="label">Take Profit:</span>
      <span class="value">${parseFloat(trade.take_profit).toFixed(5)}</span>
    </div>
    <div class="info-row">
      <span class="label">Risk/Reward:</span>
      <span class="value" style="color: #10b981; font-weight: bold;">${rr}</span>
    </div>
  </div>

  ${trade.research_summary ? `
  <div class="research-section">
    <h3>🔍 Real-time Research Summary</h3>
    <p>${trade.research_summary}</p>
  </div>
  ` : ''}

  <div class="analysis-section">
    <h3>📊 Detailed Analysis</h3>
    <p style="line-height: 1.6; color: #334155;">${trade.analysis}</p>
  </div>

  ${trade.notes ? `
  <div class="notes-section">
    <strong>⚠️ Important Notes:</strong><br>
    ${trade.notes}
  </div>
  ` : ''}

  <div class="footer">
    <p><strong>Automated Trading Analysis System</strong></p>
    <p>Generated: ${new Date(trade.timestamp).toLocaleString()}</p>
    <p style="font-size: 11px; margin-top: 10px;">⚠️ This is an automated analysis. Always conduct your own research before trading.</p>
  </div>
</div>
</body>
</html>
`;

const subject = `${emoji} HIGH CONFIDENCE (${confidencePercent}) - ${trade.symbol} ${trade.direction}`;

return {
  json: {
    subject: subject,
    html: html,
    trade: trade
  }
};
